"""Triton implementation of torch.linalg.inv_ex (pivoted Gauss-Jordan inversion).

Contract (from the Gems pytest that owns assertions):
  run(A, check_errors=False) -> (inverse, info)
    A        : float32 tensor of shape (*, n, n) on the target device
    inverse  : same shape / dtype as A
    info     : int32 tensor of shape A.shape[:-2]; 0 on success, k+1 when the
               k-th pivot of the elimination is exactly zero (LAPACK order)
    check_errors=True raises torch.linalg.LinAlgError when any info > 0

Design: one program per matrix, one kernel launch and two allocations per
call.  The augmented tile [A | I] is held in registers and reduced by
Gauss-Jordan elimination with partial pivoting.  Pivot selection, row swaps and
the rank-1 update use mask + reduction primitives (Triton cannot index a tile
with a runtime scalar); this keeps the whole state in registers, so no
cross-warp exchange through global memory is needed.  num_warps is selected per
(n, batch) by a bounded Triton autotune list.
"""

import logging
from collections import namedtuple

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

LinalgInvExResult = namedtuple("LinalgInvExResult", ["inverse", "info"])


@triton.autotune(
    configs=[
        triton.Config({}, num_warps=1),
        triton.Config({}, num_warps=2),
        triton.Config({}, num_warps=4),
        triton.Config({}, num_warps=8),
    ],
    key=["n", "l0"],
)
@triton.jit
def _gj_inv_kernel(
    A,
    OUT,
    INFO,
    n,
    a_row,
    a_col,
    l0,
    s0,
    l1,
    s1,
    l2,
    s2,
    l3,
    s3,
    BLOCK_N: tl.constexpr,
    RIGHT0: tl.constexpr,
):
    pid = tl.program_id(0)

    # Flattened batch offset of this matrix (levels are innermost-first).
    b = pid
    off = 0
    d = b % l0
    b = b // l0
    off += d * s0
    d = b % l1
    b = b // l1
    off += d * s1
    d = b % l2
    b = b // l2
    off += d * s2
    d = b % l3
    off += d * s3

    rows = tl.arange(0, BLOCK_N)
    cols = tl.arange(0, 2 * BLOCK_N)
    left = cols < RIGHT0
    cidx = tl.where(left, cols, cols - RIGHT0)

    row_ok = rows < n
    col_ok = cidx < n

    # Left half: A, right half: identity (padded diagonal included, so padded
    # lanes are algebraically neutral).
    amask = left[None, :] & row_ok[:, None] & col_ok[None, :]
    aptr = A + off + rows[:, None] * a_row + cidx[None, :] * a_col
    avals = tl.load(aptr, mask=amask, other=0.0).to(tl.float32)
    aug = tl.where(
        left[None, :],
        avals,
        tl.where(rows[:, None] == cidx[None, :], 1.0, 0.0),
    )

    singular = 0
    for k in range(0, n):
        # ---- pivot search over rows in [k, n) ------------------------------
        colk = tl.sum(tl.where(cols[None, :] == k, aug, 0.0), axis=1)
        av = tl.abs(colk)
        av = tl.where(rows < k, -1.0, av)
        av = tl.where(row_ok, av, -1.0)
        pval = tl.max(av, axis=0)
        prow = tl.min(tl.where(av == pval, rows, BLOCK_N), axis=0)

        # ---- fetch rows k and prow ----------------------------------------
        row_k = tl.sum(tl.where(rows[:, None] == k, aug, 0.0), axis=0)
        row_p = tl.sum(tl.where(rows[:, None] == prow, aug, 0.0), axis=0)

        # ---- swap, then scale the pivot row (1/0 replaced by 1) ------------
        # The search value is |column|, so recover the signed pivot element
        # A[k, k] (after the swap) for the scaling factor.
        pv = tl.sum(tl.where(cols == k, row_p, 0.0), axis=0)
        rcp = 1.0 / tl.where(pv == 0.0, 1.0, pv)
        newk = row_p * rcp
        aug = tl.where(
            rows[:, None] == k,
            newk[None, :],
            tl.where(rows[:, None] == prow, row_k[None, :], aug),
        )

        # ---- eliminate column k from every other row ----------------------
        f = tl.sum(tl.where(cols[None, :] == k, aug, 0.0), axis=1)
        f = tl.where(rows == k, 0.0, f)
        aug = aug - f[:, None] * newk[None, :]

        singular = tl.where((pv == 0.0) & (singular == 0), k + 1, singular)

    # Right half now holds the inverse.
    o_ptr = OUT + pid * (n * n) + rows[:, None] * n + cidx[None, :]
    o_mask = (cols >= RIGHT0)[None, :] & row_ok[:, None] & col_ok[None, :]
    tl.store(o_ptr, aug.to(OUT.dtype.element_ty), mask=o_mask)
    tl.store(INFO + pid, singular.to(tl.int32))


@triton.jit
def _info_flag_kernel(INFO, FLAG, B, BLOCK_B: tl.constexpr):
    """Reduce the per-matrix info values to a single 0/1 flag on device."""
    offs = tl.arange(0, BLOCK_B)
    acc = 0
    for base in range(0, B, BLOCK_B):
        vals = tl.load(INFO + base + offs, mask=(base + offs) < B, other=0)
        acc = tl.maximum(acc, tl.max(tl.abs(vals), axis=0))
    tl.store(FLAG, (acc != 0).to(tl.int32))


_BLOCK = {}


def _block(n):
    bn = _BLOCK.get(n)
    if bn is None:
        bn = max(4, triton.next_power_of_2(n))
        _BLOCK[n] = bn
    return bn


def _batch_levels(batch_shape, batch_strides):
    """Innermost-first (dim, stride) levels, merging contiguous neighbours."""
    dims = []
    sts = []
    for d, s in zip(reversed(batch_shape), reversed(batch_strides)):
        if dims and sts[-1] * dims[-1] == s:
            dims[-1] *= d
        else:
            dims.append(d)
            sts.append(s)
    if len(dims) > 4:
        raise NotImplementedError("linalg_inv_ex: unsupported batch stride layout")
    while len(dims) < 4:
        dims.append(1)
        sts.append(0)
    return dims[0], sts[0], dims[1], sts[1], dims[2], sts[2], dims[3], sts[3]


def linalg_inv_ex(A, *, check_errors=False):
    """Compute the inverse of a square matrix.

    Args:
        A: Input tensor of shape (*, n, n).
        check_errors: If True, raises an error if the matrix is singular.

    Returns:
        A namedtuple (inverse, info) where:
        - inverse: The inverse matrix of shape (*, n, n).
        - info: An int32 tensor. 0 indicates success; a positive integer i
          indicates that the i-th diagonal element of U in the LU
          decomposition is exactly zero.
    """
    logger.debug("GEMS LINALG_INV_EX")
    n = A.shape[-1]
    batch_shape = A.shape[:-2]
    nn = n * n

    out = torch.empty(A.shape, dtype=A.dtype, device=A.device)
    info = torch.empty(batch_shape, dtype=torch.int32, device=A.device)
    if nn == 0:
        return LinalgInvExResult(out, info)
    B = A.numel() // nn
    if B == 0:
        return LinalgInvExResult(out, info)

    if A.is_contiguous():
        a_row = n
        a_col = 1
        l0, s0, l1, s1, l2, s2, l3, s3 = B, nn, 1, 0, 1, 0, 1, 0
    else:
        st = A.stride()
        a_row = st[-2]
        a_col = st[-1]
        l0, s0, l1, s1, l2, s2, l3, s3 = _batch_levels(batch_shape, st[:-2])

    block_n = _block(n)
    _gj_inv_kernel[(B,)](
        A,
        out,
        info,
        n,
        a_row,
        a_col,
        l0,
        s0,
        l1,
        s1,
        l2,
        s2,
        l3,
        s3,
        block_n,
        block_n,
    )

    if check_errors:
        flag = torch.empty(1, dtype=torch.int32, device=A.device)
        bb = max(1, triton.next_power_of_2(min(B, 1024)))
        _info_flag_kernel[(1,)](info, flag, B, bb, num_warps=1)
        if flag.item() != 0:
            raise torch.linalg.LinAlgError(
                "torch.linalg.inv_ex: The diagonal element of the LU "
                "decomposition is zero."
            )

    return LinalgInvExResult(out, info)
